    @('identity/Identity-Architecture.md','ID-ARCH','end-to-end identity authority, assurance, provisioning, session, and revocation boundaries','institution issuer, person and workload lifecycle events, policy, and relying-party request','normalized identity claims, assurance context, authorization inputs, and audit trail','each institution remains its identity authority while common protocols enable interoperability','a common service becomes a hidden global identity provider or local revocation fails to propagate'),
    @('identity/Identity-Separation.md','ID-SEP','separation of person, role, device, workload, social actor, and service identities','principal identifier, identity kind, authority, affiliation, role, and requested operation','unambiguous subject context and policy decision without identity conflation','one human may hold multiple institutional and non-institutional personas and devices','an identifier from one namespace is accepted as authority in another namespace'),
    @('identity/OIDC-OAuth2.md','ID-OIDC','portable authentication and delegated API authorization profiles','authorization request with PKCE, issuer metadata, client policy, scopes, and user session','validated tokens or codes with bounded audience, lifetime, assurance, and stable errors','browser, native client, issuer, authorization server, resource server, and redirect boundary','token substitution, redirect abuse, code interception, mix-up, or audience confusion succeeds'),
    @('identity/RBAC.md','ID-RBAC','coarse-grained role assignment for understandable administrative authorization','verified principal, institution, role definition, assignment authority, and resource scope','effective roles, decision inputs, assignment history, and removal state','role administration remains distinct from service-specific permission enforcement','role accumulation or ambiguous inheritance grants authority beyond current duties'),
    @('identity/SCIM-Provisioning.md','ID-SCIM','standards-based account and group lifecycle synchronization','authenticated SCIM request, stable external identifier, attributes, version, and lifecycle state','idempotent user or group state, conflict result, audit event, and deprovision confirmation','institution systems of record drive downstream accounts without sharing their databases','out-of-order updates, identifier reuse, or failed deprovisioning leaves unauthorized access'),
    @('identity/Service-Accounts.md','ID-SVC','non-human service principal ownership, credential lifecycle, and authorization','declared service owner, purpose, workload, requested permissions, and expiry policy','unique service principal, short-lived credentials, usage evidence, and revocation route','automation is attributable without impersonating a person or sharing credentials','an orphaned, shared, interactive, or over-privileged service account persists'),
    @('identity/Session-and-Token-Management.md','ID-SESS','session creation, token validation, renewal, revocation, and logout propagation','authenticated principal, assurance, client, audience, device context, and policy','bounded session and tokens, rotation state, revocation signal, and audit evidence','browser or native client state crosses issuer, gateway, and resource-service boundaries','stolen, replayed, overlong, wrong-audience, or revoked tokens remain usable'),
    @('identity/Workload-Identity.md','ID-WORK','cryptographic identity for software workloads without embedded static secrets','attested workload, namespace, service account, environment, and requested audience','short-lived workload credential, trust chain, policy decision, and rotation evidence','scheduler and identity issuer bind runtime workload state to service authorization','a copied token, compromised node, or spoofed workload gains cross-service authority')
