function Add-SubjectContract([string]$Path, [object[]]$Subject, [bool]$Institution) {
    $content = Get-Content -LiteralPath $Path -Raw
    if ($content -match '(?m)^## Subject-specific control contract$') { return }
    $binding = if ($Institution) {
        "The Algonquin deployment MUST bind these controls to Algonquin-owned identity, policy, evidence retention, and incident routes without weakening the common contract."
    } else {
        "Institution forks MUST bind these controls to local identity, policy, evidence retention, and incident routes without weakening the common contract."
    }
    $block = @"
## Subject-specific control contract

| Dimension | Required definition |
|---|---|
| Owned responsibility | $($Subject[2]) |
| Authoritative input | $($Subject[3]) |
| Authoritative output | $($Subject[4]) |
| Primary trust boundary | $($Subject[5]) |
| Unsafe failure to prevent | $($Subject[6]) |

- **$($Subject[1])-001:** The owner MUST implement the responsibility and preserve the input-to-output evidence chain shown above.
- **$($Subject[1])-002:** The enforcement point MUST fail closed when identity, policy version, integrity, freshness, or required context cannot be verified.
- **$($Subject[1])-003:** A release MUST include a positive conformance case, an unauthorized or malformed case, a dependency-loss case, and a regression case for the unsafe failure.
- **$($Subject[1])-004:** Exceptions MUST identify scope, compensating controls, approver, expiry, monitoring, and a removal plan; permanent undocumented bypasses are prohibited.

$binding

### Verification scenarios

1. Prove the authoritative input produces the declared output with the active policy version and attributable actor or workload.
2. Alter or omit one trust-bearing input and prove the request is denied with a stable reason while protected content is excluded from diagnostics.
3. Make the principal dependency unavailable and prove the component enters its documented fail-closed or bounded degraded mode.
4. Revoke or expire the authority and prove cached state, sessions, queued work, and replicas stop accepting it within the declared propagation objective.

"@
    $anchor = '## Decision traceability'
    if (-not $content.Contains($anchor)) { throw "Missing insertion anchor: $Path" }
    $content = $content.Replace($anchor, "$block`r`n$anchor")
    Set-Content -LiteralPath $Path -Value $content -Encoding utf8NoBOM
}

$common = Join-Path $Root 'common/psdc-architecture/docs'
$algonquin = Join-Path $Root 'institutions/algonquin/algonquin-architecture/docs'
foreach ($subject in $subjects) {
    Add-SubjectContract (Join-Path $common $subject[0]) $subject $false
    Add-SubjectContract (Join-Path $algonquin $subject[0]) $subject $true
}

Write-Output "Added subject-specific contracts to $($subjects.Count * 2) high-risk security and identity specifications."
